$outgoing=db()->query("SELECT * FROM api_pairing_requests WHERE direction='outgoing' ORDER BY id DESC LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);
$conns=db()->query("SELECT * FROM api_connections ORDER BY id DESC LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);
function status_badge($s){ $c=$s==='approved'||$s==='active'||$s==='ok'?'ok':($s==='pending'?'warn':'danger'); return '<span class="badge '.$c.'">'.e((string)$s).'</span>'; }
?>
