<div class="card"><h3>Request Keluar</h3><table class="table"><tr><th>Waktu</th><th>Tujuan</th><th>URL</th><th>Scope</th><th>Status</th><th>Aksi</th></tr><?php foreach($outgoing as $r): ?><tr><td><?php echo e($r['created_at']); ?></td><td><?php echo e($r['target_name']); ?></td><td><?php echo e($r['target_base_url']); ?></td><td><?php echo e($r['requested_scope']); ?></td><td><?php echo status_badge($r['status']); ?></td><td><form method="post" action="<?php echo e(base_url('admin/api_pairing_action.php')); ?>"><input type="hidden" name="_csrf" value="<?php echo e(csrf_generate_token()); ?>"><input type="hidden" name="act" value="check_status"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><button class="btn btn-light">Cek Status</button></form></td></tr><?php endforeach; if(!$outgoing): ?><tr><td colspan="6" class="muted">Belum ada request keluar.</td></tr><?php endif; ?></table></div>
<div class="card"><h3>Koneksi Aktif</h3><table class="table"><tr><th>Nama</th><th>Jenis</th><th>URL Remote</th><th>Scope</th><th>Status</th><th>Test</th></tr><?php foreach($conns as $c): ?><tr><td><?php echo e($c['connection_name']); ?></td><td><?php echo e($c['connection_type']); ?></td><td><?php echo e($c['remote_base_url']); ?></td><td><?php echo e($c['access_scope']); ?></td><td><?php echo status_badge($c['status']); ?><br><small><?php echo e($c['last_test_message']??''); ?></small></td><td><form method="post" action="<?php echo e(base_url('admin/api_pairing_action.php')); ?>"><input type="hidden" name="_csrf" value="<?php echo e(csrf_generate_token()); ?>"><input type="hidden" name="act" value="test_connection"><input type="hidden" name="id" value="<?php echo (int)$c['id']; ?>"><button class="btn btn-light">Test</button></form></td></tr><?php endforeach; if(!$conns): ?><tr><td colspan="6" class="muted">Belum ada koneksi aktif.</td></tr><?php endif; ?></table></div>
